-- E-commerce OLTP source schema: the "production database" the warehouse copies from.
--
-- Reset script: drops and recreates all tables (data is regenerated by seed.py).
--   docker exec -i oltp-db psql -U postgres -d oltp_db -v ON_ERROR_STOP=1 < postgres-source/ecommerce.sql
--
-- Change-tracking columns on every table, used by incremental sync:
--   created_at  when the row was inserted
--   updated_at  last modification; maintained by trigger, the sync watermark column
--   deleted_at  soft delete marker; NULL = live row

BEGIN;

DROP TABLE IF EXISTS payments, order_items, orders, products, users CASCADE;
DROP FUNCTION IF EXISTS set_updated_at() CASCADE;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

CREATE TABLE users (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email       text        NOT NULL UNIQUE,
    first_name  text        NOT NULL,
    last_name   text        NOT NULL,
    city        text,
    country     text,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz
);

CREATE TABLE products (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku         text          NOT NULL UNIQUE,
    name        text          NOT NULL,
    category    text          NOT NULL,
    unit_price  numeric(10,2) NOT NULL CHECK (unit_price >= 0),
    created_at  timestamptz   NOT NULL DEFAULT now(),
    updated_at  timestamptz   NOT NULL DEFAULT now(),
    deleted_at  timestamptz
);

CREATE TABLE orders (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       bigint        NOT NULL REFERENCES users (id),
    -- No FK: campaigns are owned by marketing and arrive as a CSV, not as an OLTP table.
    -- The two sources only meet in the warehouse.
    campaign_id   int,
    status        text          NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled')),
    -- Denormalized by the app at checkout; should equal the sum of its order_items.
    total_amount  numeric(12,2) NOT NULL CHECK (total_amount >= 0),
    created_at    timestamptz   NOT NULL DEFAULT now(),
    updated_at    timestamptz   NOT NULL DEFAULT now(),
    deleted_at    timestamptz
);

CREATE TABLE order_items (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id    bigint        NOT NULL REFERENCES orders (id),
    product_id  bigint        NOT NULL REFERENCES products (id),
    quantity    int           NOT NULL CHECK (quantity > 0),
    -- Price at time of purchase. products.unit_price can change later; this must not.
    unit_price  numeric(10,2) NOT NULL CHECK (unit_price >= 0),
    created_at  timestamptz   NOT NULL DEFAULT now(),
    updated_at  timestamptz   NOT NULL DEFAULT now(),
    deleted_at  timestamptz,
    UNIQUE (order_id, product_id)
);

CREATE TABLE payments (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id    bigint        NOT NULL REFERENCES orders (id),
    method      text          NOT NULL
                CHECK (method IN ('card', 'paypal', 'bank_transfer')),
    amount      numeric(12,2) NOT NULL CHECK (amount >= 0),
    created_at  timestamptz   NOT NULL DEFAULT now(),
    updated_at  timestamptz   NOT NULL DEFAULT now(),
    deleted_at  timestamptz
);

-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------

-- Postgres does not index foreign keys automatically.
CREATE INDEX orders_user_id_idx          ON orders (user_id);
CREATE INDEX order_items_order_id_idx    ON order_items (order_id);
CREATE INDEX order_items_product_id_idx  ON order_items (product_id);
CREATE INDEX payments_order_id_idx       ON payments (order_id);

-- Incremental sync runs `WHERE updated_at > :watermark` against every table.
-- Without these, each sync is a full table scan on the production database.
CREATE INDEX users_updated_at_idx        ON users (updated_at);
CREATE INDEX products_updated_at_idx     ON products (updated_at);
CREATE INDEX orders_updated_at_idx       ON orders (updated_at);
CREATE INDEX order_items_updated_at_idx  ON order_items (updated_at);
CREATE INDEX payments_updated_at_idx     ON payments (updated_at);

-- ---------------------------------------------------------------------------
-- updated_at trigger
-- ---------------------------------------------------------------------------

-- Postgres has no "ON UPDATE CURRENT_TIMESTAMP". Without this trigger, an UPDATE that
-- forgets to set updated_at is invisible to incremental sync.
--
-- now() is the *transaction start* time, not the commit time. A long transaction can
-- commit after a sync has already moved the watermark past its updated_at, and its rows
-- are then missed. Real pipelines re-read a small overlap window; CDC avoids it entirely.
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER users_set_updated_at        BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER products_set_updated_at     BEFORE UPDATE ON products
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER orders_set_updated_at       BEFORE UPDATE ON orders
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER order_items_set_updated_at  BEFORE UPDATE ON order_items
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER payments_set_updated_at     BEFORE UPDATE ON payments
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMIT;
